- How would you optimize space if n is large (e.g., using rolling arrays)?
- How would you adapt to allow at most k blocks instead of exactly k, and still reconstruct the blocks?

## Why This Is Asked
Tests the ability to model partitioning with a non-linear block value, a common DP pattern in beginner interviews. Requires prefix sums for O(1) block sums, a clear state definition over prefix length and blocks, and backtracking to output endpoints.

## Key Concepts
- DP on partitions with exact k blocks
- Prefix sums for subarray sums
- State: dp[i][t], parent pointers for reconstruction

## Code Example
```javascript
function maxRevenue(A, k) {
  const n = A.length;
  const S = Array(n+1).fill(0);
  for (let i=1;i<=n;i++) S[i] = S[i-1] + A[i-1];
  const dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
  const par = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
  for (let i=1;i<=n;i++) dp[i][1] = S[i]*i;
  for (let t=2;t<=k;t++) {
    for (let i=t;i<=n;i++) {
      for (let p=t-1;p<=i-1;p++) {
        const val = dp[p][t-1] + (S[i]-S[p])*(i-p);
        if (val > dp[i][t]) { dp[i][t] = val; par[i][t] = p; }
      }
    }
  }
  // reconstruction
  let i=n, t=k; const ends=[];
  while (t>0) { const p = par[i][t]; ends.push([p+1, i]); i = p; t--; }
  ends.reverse();
  return {value: dp[n][k], windows: ends};
}
```

## Follow-up Questions
- How would you optimize to O(nk) time using a trick for monotone optima?
- How would you adapt if windows could overlap or if k is variable?

## Why This Is Asked
Tests DP with an extra resource dimension (shields) on a classic grid path. Demonstrates handling of constrained resources, 3D DP states, and reconstruction.

## Key Concepts
- DP with an additional dimension for resources (k)
- Transition with/without consuming a shield
- Path reconstruction via parent pointers

## Code Example
```javascript
function maxGridPath(grid, K) {
  const n = grid.length, m = grid[0].length;
  const NEG = -Infinity;
  const dp = Array.from({length: n}, () => Array.from({length: m}, () => Array(K+1).fill(NEG)));
  dp[0][0][0] = grid[0][0];
  for (let i=0; i<n; i++) {
    for (let j=0; j<m; j++) {
      for (let k=0; k<=K; k++) {
        const v = grid[i][j];
        if (i>0) dp[i][j][k] = Math.max(dp[i][j][k], dp[i-1][j][k] + v);
        if (j>0) dp[i][j][k] = Math.max(dp[i][j][k], dp[i][j-1][k] + v);
        if (k>0 && v < 0) {
          if (i>0) dp[i][j][k] = Math.max(dp[i][j][k], dp[i-1][j][k-1]);
          if (j>0) dp[i][j][k] = Math.max(dp[i][j][k], dp[i][j-1][k-1]);
        }
      }
    }
  }
  return Math.max(...dp[n-1][m-1]);
}
```

## Follow-up Questions
- How would you recover one optimal path and its moves?
- How to optimize space to O(n*m*K)?

## Why This Problem Is Asked

This problem explores non-overlapping palindromic substring selection using a two-dimensional DP that tracks prefix length and the number of selected substrings. It tests palindrome precomputation, transition logic, and solution reconstruction under constraints.

## Key Concepts

- **Palindrome table**: pal[l][r] indicates whether s[l..r] is a palindrome
- **DP state**: dp[i][t] represents the maximum total length obtainable from prefix s[0..i] using exactly t substrings
- **Transition**: Either skip the current position or end a palindrome at i (starting at some l)
- **Reconstruction**: Use parent pointers to backtrack and retrieve the selected substrings

## Code Example

```javascript
function maxPalindromes(s, k) {
  const n = s.length;
  const pal = Array.from({ length: n }, () => Array(n).fill(false));

  for (let i = 0; i < n; i++) pal[i][i] = true;
  for (let len = 2; len <= n; len++) {
    for (let l = 0; l + len - 1 < n; l++) {
      const r = l + len - 1;
      if (s[l] === s[r] && (len === 2 || pal[l+1][r-1])) {
        pal[l][r] = true;
      }
    }
  }

  const dp = Array.from({ length: n }, () => Array(k+1).fill(0));
  const parent = Array.from({ length: n }, () => Array(k+1).fill(null));

  for (let i = 0; i < n; i++) {
    for (let t = 1; t <= k; t++) {
      dp[i][t] = dp[i-1]?.[t] ?? 0;
      parent[i][t] = { skip: true };

      for (let l = 0; l <= i; l++) {
        if (pal[l][i]) {
          const prev = l > 0 ? dp[l-1][t-1] : 0;
          const val = prev + (i - l + 1);
          if (val > dp[i][t]) {
            dp[i][t] = val;
            parent[i][t] = { skip: false, l, t: t-1 };
          }
        }
      }
    }
  }

  const result = [];
  let i = n - 1, t = k;
  while (i >= 0 && t > 0) {
    const choice = parent[i][t];
    if (!choice.skip) {
      result.unshift([choice.l, i]);
      t = choice.t;
      i = choice.l - 1;
    } else {
      i--;
    }
  }

  return { maxLength: dp[n-1][k], substrings: result };
}
```

## Why This Is Asked
Tests ability to design an optimized DP on a circular constraint and track the number of optimal solutions.

## Key Concepts
- DP on linear sequences with spacing (dp[i] = max(dp[i-1], dp[i-d] + v[i]))
- Reducing circularity to two linear cases (include first vs exclude first)
- Counting distinct optimal subsets with tie handling (sum counts when equal)

## Code Example
```javascript
function linearDP(arr, d){
  const n = arr.length; const dp = Array(n+1).fill(0); const ways = Array(n+1).fill(0);
  dp[0] = 0; ways[0] = 1;
  for(let i=1;i<=n;i++){
    const take = arr[i-1] + (i-d>=0 ? dp[i-d] : 0);
    const skip = dp[i-1];
    if(take>skip){ dp[i]=take; ways[i]=(i-d>=0 ? ways[i-d] : 1); }
    else if(take<skip){ dp[i]=skip; ways[i]=ways[i-1]; }
    else { dp[i]=skip; ways[i] = ((i-d>=0 ? ways[i-d] : 1) + ways[i-1]); }
  }
  return [dp[n], ways[n]];
}

function maxCircular(v, d){
  const [bestA, cntA] = linearDP(v.slice(1), d); // exclude first
  const n = v.length;
  const seg = (n > 2*d-1) ? v.slice(d, n-d+1) : [];
  const [bestBseg, cntBseg] = seg.length ? linearDP(seg, d) : [0,1];
  const bestB = v[0] + bestBseg;
  if(bestA > bestB) return [bestA, cntA];
  if(bestB > bestA) return [bestB, cntBseg];
  return [bestA, cntA + cntBseg];
}
```

## Follow-up Questions
- How would you extend to allow a variable distance per pair or weighted distance penalties?
- How would you test correctness and performance on worst-case inputs?

## Why This Is Asked
Assesses ability to turn path-based objectives into simple local transitions without extraneous state. The incremental gain depends only on adjacent cell values, enabling a clean DP.

## Key Concepts
- Grid DP with monotone moves
- Backpointers for path reconstruction
- Space optimization potential

## Code Example
```javascript
function maxAscents(grid){
  const n=grid.length, m=grid[0].length;
  const dp=Array.from({length:n}, ()=>Array(m).fill(0));
  const par=Array.from({length:n}, ()=>Array(m).fill(null));
  for(let i=0;i<n;i++){
    for(let j=0;j<m;j++){
      if(i===0 && j===0) continue;
      let top=-Infinity, left=-Infinity;
      if(i>0) top = dp[i-1][j] + (grid[i-1][j] < grid[i][j] ? 1:0);
      if(j>0) left = dp[i][j-1] + (grid[i][j-1] < grid[i][j] ? 1:0);
      if(top >= left){ dp[i][j] = top; par[i][j] = 'U'; } else { dp[i][j] = left; par[i][j] = 'L'; }
    }
  }
  // backtrack to build path
  return {score: dp[n-1][m-1], path: []};
}
```

## Why This Is Asked
This tests formulating a DP over partitions with a subarray-internal metric.

## Key Concepts
- Partition DP
- Prefix sums
- Reconstruction pointers

## Code Example
```javascript
// DP skeleton
function maxValue(A, k) {
  const n = A.length;
  const pref = new Array(n+1).fill(0);
  for (let i=0;i<n;i++) pref[i+1] = pref[i]+A[i];
  const dp = Array.from({length:n+1}, ()=> Array(k+1).fill(-Infinity));
  const cut = Array.from({length:n+1}, ()=> Array(k+1).fill(-1));
  dp[0][0] = 0;
  for (let i=1;i<=n;i++) {
     for (let t=1;t<=Math.min(i,k);t++) {
        let maxVal = -Infinity; let bestP = -1; let curMax = -Infinity;
        for (let p=i-1; p>=t-1; p--) {
           curMax = Math.max(curMax, A[p]);
           const val = dp[p][t-1] + (pref[i]-pref[p]) - curMax;
           if (val>maxVal) { maxVal=val; bestP=p; }
        }
        dp[i][t] = maxVal; cut[i][t] = bestP;
     }
  }
  return {value: dp[n][k], cuts: cut};
}
```

## Follow-up Questions
- What is the time complexity and how would you optimize to O(nk) with a deque?
- How would you reconstruct the exact subarray endpoints?

## Why This Is Asked
Tests DP on partitioning with a minimax objective, a practical budgeting scenario.

## Key Concepts
- DP over partitions; - Recurrence: min over j of max of subproblem and block sum; - Reconstruction via parent pointers.

## Code Example
```javascript
// sketch
function partitionMinMaxSum(a, k) {
  const n = a.length;
  const pref = new Array(n+1).fill(0);
  for (let i=0;i<n;i++) pref[i+1]=pref[i]+a[i];
  const dp = Array.from({length:n},()=>new Array(k+1).fill(Infinity));
  const par = Array.from({length:n},()=>new Array(k+1).fill(-1));
  for (let i=0;i<n;i++) dp[i][1]=pref[i+1];
  for (let t=2;t<=k;t++){
    for (let i=0;i<n;i++){
      for (let j=0;j<i;j++){
        const val = Math.max(dp[j][t-1], pref[i+1]-pref[j+0]);
        if (val<dp[i][t]){ dp[i][t]=val; par[i][t]=j; }
      }
    }
  }
  return {best: dp[n-1][Math.min(k,n)], cuts: par};
}
```

## Follow-up Questions
- How would you implement a monotone-queue or divide-and-conquer optimization here?
- How would you adapt for exactly k vs at most k blocks and output exact cut points?

## Why This Is Asked
Explores a new DP angle: subarray-level min as value, exact k non-overlapping blocks, with clear reconstruction.

## Key Concepts
- Partition DP with exact block count
- Precomputation of subarray minima
- Backtracking to obtain endpoints

## Code Example
```javascript
// Assumes A is 1-indexed, n = A.length-1, k given
function maxSumMinSubarrays(A, n, k) {
  const M = Array.from({length: n+2}, ()=>Array(n+2).fill(0));
  for (let l=1; l<=n; l++) {
    let m = A[l];
    for (let r=l; r<=n; r++) {
      m = Math.min(m, A[r]);
      M[l][r] = m;
    }
  }
  const dp = Array.from({length: n+1}, ()=>Array(k+1).fill(-Infinity));
  const opt = Array.from({length: n+1}, ()=>Array(k+1).fill(-1));
  dp[0][0] = 0;
  for (let i=1; i<=n; i++) {
    for (let t=1; t<=k; t++) {
      for (let l=1; l<=i; l++) {
        const cand = dp[l-1][t-1] + M[l][i];
        if (cand > dp[i][t]) { dp[i][t] = cand; opt[i][t] = l; }
      }
    }
  }
  // backtrack for endpoints
  let i = n, t = k, blocks = [];
  while (t > 0) {
    const l = opt[i][t];
    blocks.push([l, i]);
    i = l-1; t--;
  }
  blocks.reverse();
  return {sum: dp[n][k], blocks};
}
```

## Why This Is Asked

Tests ability to design DP over partitions with a non-linear segment value, including reconstruction of segments. Encourages using prefix sums for fast segment sums and careful indexing to enforce exactly k non-empty contiguous blocks. Also invites discussion of time/space trade-offs and potential optimizations.

## Key Concepts

- Prefix sums for quick segment sums
- DP over partitions with exact k blocks
- Reconstructing the chosen boundaries via a prev table

## Code Example

```javascript
function maxPartition(A, k, c){
  const n = A.length;
  const P = new Array(n+1).fill(0);
  for(let i=1;i<=n;i++) P[i] = P[i-1] + A[i-1];
  const dp = Array.from({length:n+1},()=>new Array(k+1).fill(-Infinity));
  const prev = Array.from({length:n+1},()=>new Array(k+1).fill(-1));
  dp[0][0] = 0;
  for(let i=1;i<=n;i++) dp[i][1] = (P[i]-P[0])**2 - c, prev[i][1] = 0;
  for(let t=2;t<=k;t++){
    for(let i=t;i<=n;i++){
      for(let j=t-1;j<=i-1;j++){
        const val = dp[j][t-1] + (P[i]-P[j])**2 - c;
        if(val > dp[i][t]){ dp[i][t] = val; prev[i][t] = j; }
      }
    }
  }
  // recover endpoints via backtracking
  return {best: dp[n][k], prev};
}
``` 

